use Illuminate\Database\Schema\Blueprint;
use Illuminate\Support\Facades\Schema;

Schema::create('variants', function (Blueprint $t) {
    $t->id(); $t->string('title'); $t->unsignedInteger('price_minor');
    $t->unsignedInteger('stock'); $t->boolean('active')->default(true);
});
Schema::create('carts', function (Blueprint $t) {
    $t->id(); $t->unsignedBigInteger('telegram_user_id')->unique();
    $t->unsignedInteger('revision')->default(1);
});
Schema::create('cart_items', function (Blueprint $t) {
    $t->foreignId('cart_id')->constrained('carts');
    $t->foreignId('variant_id')->constrained('variants');
    $t->unsignedInteger('quantity'); $t->primary(['cart_id', 'variant_id']);
});
Schema::create('cart_quotes', function (Blueprint $t) {
    $t->string('id', 32)->primary(); $t->foreignId('cart_id')->constrained('carts');
    $t->unsignedInteger('revision'); $t->json('items'); $t->unsignedBigInteger('expires_at');
});
Schema::create('orders', function (Blueprint $t) {
    $t->id(); $t->string('public_id', 24)->unique(); $t->unsignedBigInteger('telegram_user_id');
    $t->foreignId('cart_id')->constrained('carts'); $t->unsignedInteger('cart_revision');
    $t->string('quote_id', 32); $t->unsignedBigInteger('total_minor'); $t->string('status');
    $t->unique(['cart_id', 'cart_revision']);
});
Schema::create('order_items', function (Blueprint $t) {
    $t->foreignId('order_id')->constrained('orders');
    $t->foreignId('variant_id')->constrained('variants');
    $t->string('title'); $t->unsignedInteger('price_minor'); $t->unsignedInteger('quantity');
    $t->primary(['order_id', 'variant_id']);
});

use App\Services\ShopCart;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\Route;

$cartOwner = static function (Request $request): int {
    abort_unless(is_int($request->session()->get('mini_user_id'))
        && (int) $request->session()->get('mini_expires_at', 0) > time(), 401);
    return $request->session()->get('mini_user_id');
};
Route::prefix('mini/cart')->middleware('throttle:60,1')->group(function () use ($cartOwner) {
    Route::get('/', fn (Request $r, ShopCart $cart) => response()->json(
        $cart->read($cartOwner($r))
    )->header('Cache-Control', 'private, no-store'));
    Route::put('/items/{variant}', function (Request $r, ShopCart $cart, string $variant) use ($cartOwner) {
        $owner = $cartOwner($r);
        $v = $r->validate(['quantity' => 'required|integer|min:0|max:99',
            'revision' => 'required|integer|min:1']);
        return response()->json($cart->quantity($owner,
            (int) $variant, (int) $v['quantity'], (int) $v['revision']))->header('Cache-Control', 'no-store');
    })->whereNumber('variant');
    Route::post('/quote', function (Request $r, ShopCart $cart) use ($cartOwner) {
        $owner = $cartOwner($r);
        $v = $r->validate(['revision' => 'required|integer|min:1']);
        return response()->json($cart->quote($owner, (int) $v['revision']))->header('Cache-Control', 'no-store');
    });
    Route::post('/checkout', function (Request $r, ShopCart $cart) use ($cartOwner) {
        $owner = $cartOwner($r);
        $v = $r->validate(['revision' => 'required|integer|min:1',
            'quote_id' => ['required', 'regex:/\A[a-f0-9]{32}\z/']]);
        $result = $cart->checkout($owner, (int) $v['revision'], $v['quote_id']);
        return response()->json($result, $result['created'] ? 201 : 200)->header('Cache-Control', 'no-store');
    });
});

async function cartRequest(path, method = 'GET', body) {
  const response = await fetch('/mini/cart' + path, {
    method, credentials: 'same-origin',
    headers: {'Accept': 'application/json', 'Content-Type': 'application/json',
      'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content},
    ...(body === undefined ? {} : {body: JSON.stringify(body)})
  });
  if (!response.ok) throw new Error('Запрос корзины: ' + response.status);
  return response.json();
}
const initial = await cartRequest('');
const changed = await cartRequest('/items/1', 'PUT', {quantity: 1, revision: initial.revision});
const offer = await cartRequest('/quote', 'POST', {revision: changed.revision});
console.log(offer); // Покажите эти цены покупателю до следующего действия.
const checkoutBody = {revision: offer.revision, quote_id: offer.quote_id};
// Выполнить после подтверждения покупателем:
const order = await cartRequest('/checkout', 'POST', checkoutBody);
const repeated = await cartRequest('/checkout', 'POST', checkoutBody);
